head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf08051";
scwin.SCREN_PROCS_TP_CD_01 = "01";  // 조회 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.NO_EXCEL_DATA = "해당데이터가 없습니다. 조회후 다운받으십시요.";  // 엑셀 다운로드 데이터 없음 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.grd2 = null;
scwin.grd = null;
scwin.grd3 = null;
scwin.grd4 = null;
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
scwin.dts = null;
scwin.dts_EtnInst = null;
scwin.dts2 = null;
scwin.dts3 = null;
scwin.dts4 = null;
scwin.fr_SecuGrpId = undefined;
scwin.fr_MktId = undefined;
scwin.fn_get_isurcode = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.srcUrl
    try {
        scwin.fn_get_isurcode();
        $c.util.getComponent("rd_rdo11").setValue("1");
        const vEaryRedmpt = $c.util.getParameter($c.frame.srcUrl, "isEaryRedmpt");
        if (vEaryRedmpt === "Y") {
            $c.util.getComponent('img_Etnlist').setSelectedIndex(3);
            await scwin.newCreateFrame3();
        } else {
            $c.util.getComponent('img_Etnlist').setSelectedIndex(1);
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf08051.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.fr_SecuGrpId =SECUGRP_ID_EN; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf08051' }); }

try { scwin.fr_MktId =scwin.getMktId(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf08051' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.grd2 = $c.util.getComponent('grd2');
        scwin.grd = $c.util.getComponent('grd');
        scwin.grd3 = $c.util.getComponent('grd3');
        scwin.grd4 = $c.util.getComponent('grd4');
        scwin.dts = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts')) : $c.util.getComponent('dts');
        scwin.dts_EtnInst = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_EtnInst')) : $c.util.getComponent('dts_EtnInst');
        scwin.dts2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts2')) : $c.util.getComponent('dts2');
        scwin.dts3 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts3')) : $c.util.getComponent('dts3');
        scwin.dts4 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts4')) : $c.util.getComponent('dts4');
        scwin.fn_get_isurcode = scwin.tx_script_dts_EtnInst;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf08051.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Etnlist_onselchanged
 * @description img_Etnlist onselchanged 이벤트
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Etnlist_onselchanged = async function (nIndex) {
    try {
        if (nIndex === 1) {
            $c.util.getComponent("rd_rdo11").setValue("1");
            $c.util.getComponent("rd_rdo12").setValue("2");
            $c.util.getComponent("ipt_txb_ISU_CD").setValue("");
            $c.util.getComponent("ipt_txb_ISU_NM").setValue("");
            $c.util.getComponent('slc_cmb_ISUR_CD').setSelectedIndex(0);
        } else {
            if (nIndex === 2) {
                await scwin.search2();
            } else {
                if (nIndex === 3) {
                    await scwin.search3();
                } else {
                    if (nIndex === 4) {
                        await scwin.search4();
                    }
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf08051.img_Etnlist_onselchanged' }); }
};

/**
 * @method
 * @name dts_onloaderror
 * @description dts onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf08051.dts_onloaderror" });
    }
};

/**
 * @method
 * @name dts_onloadcompleted
 * @description txb_TotCnt 을(를) 값을 넣는다 외
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_onloadcompleted = function (rowcount) {
    try {
        $c.util.getComponent("ipt_txb_TotCnt").setValue("총 건수 : " + rowcount);
        void 0;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf08051.dts_onloadcompleted" });
    }
};

