 * @description img_Excel 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function () {
    try {
        /* TODO Stage2: 접속 로그 저장 보류(공급사 doLogSave — 운영 필요 여부 회신 ㉤ 뒤 결정) $c.fil.doLogSave(scwin.vScrenID, $c.fil.SCREN_PROCS_TP_CD_07); */
        if (scwin.dts.CountRow > 0) {
            scwin.grd.GridToExcel(scwin.getSecuGrpNm(scwin.fr_SecuGrpId) + "상장폐지내역", "", "8");
        } else {
            await $c.win.alert(scwin.NO_EXCEL_DATA);
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf08051.img_Excel_onclick' }); }
};

