/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    let url = "/etn/EtnMktAct.do?method=searchDelist";
    if ($c.util.getComponent('rd_rdo11').getValue() === "1") {
        url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ISU + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + ipt_txb_ISU_CD.value;
    } else {
        if ($c.util.getComponent('rd_rdo12').getValue() === "1") {
            if (slc_cmb_ISUR_CD.index === 0) {
                url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ALL + "&TRS_IDX=" + TRS_IDX_SELECT;
            } else {
                url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + slc_cmb_ISUR_CD.BindColVal;
            }
        }
    }
    url += "&SCREN_ID=" + "ULDSTF08051.gfm" + "&SCREN_PROCES_TP_CD=" + scwin.SCREN_PROCS_TP_CD_01;

    await scwin.tx_script_dts();
    void 0;
};

