/**
 * @method
 * @name getParIsur
 * @description get Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function (arrPar) {
    arrPar[0] = "";
    if (img_Etnlist.selectedIndex === "1") {
        arrPar[1] = ipt_txb_ISU_NM.getValue();
    }
    arrPar[2] = scwin.fr_SecuGrpId;
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function (arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        scwin.changeRadioBtn(1);
        if (img_Etnlist.selectedIndex === "1") {
            $c.util.getComponent("ipt_txb_ISU_CD").setValue(arrPar[0].ISU_CD);
            $c.util.getComponent("ipt_txb_ISU_NM").setValue(arrPar[0].ISU_KOR_ABBRV);
            await scwin.search();
        }
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD === "D") {
        if (img_Etnlist.selectedIndex === "1") {
            $c.util.getComponent('img_Regist').setDisabled(true);
            $c.util.getComponent('img_Regist').setSrc("../img/btn_new_d.gif");
        } else {
            $c.util.getComponent('img_Regist2').setDisabled(true);
            $c.util.getComponent('img_Regist2').setSrc("../img/btn_new_d.gif");
        }
    } else {
        if (img_Etnlist.selectedIndex === "1") {
            $c.util.getComponent('img_Regist').setDisabled(false);
            $c.util.getComponent('img_Regist').setSrc("../img/btn_new.gif");
        } else {
            $c.util.getComponent('img_Regist2').setDisabled(false);
            $c.util.getComponent('img_Regist2').setSrc("../img/btn_new.gif");
        }
    }
};

/**
 * @method
 * @name getParUpdate
 * @description get Par Update 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParUpdate = function (arrPar) {
    if ($c.util.getComponent('rd_rdo11').getValue() === "1") {
        arrPar[0] = scwin.vIsurCd;
        arrPar[1] = ipt_txb_ISU_NM.value;
        arrPar[5] = ipt_txb_ISU_CD.value;
        arrPar[6] = "1";
    } else {
        if ($c.util.getComponent('rd_rdo12').getValue() === "1") {
            if (slc_cmb_ISUR_CD.index === 0) {
                arrPar[0] = scwin.vIsurCd;
                arrPar[1] = scwin.dts.getCellData(scwin.dts.getRowPosition(), "COM_NM");
                arrPar[5] = "";
                arrPar[6] = "3";
            } else {
                arrPar[0] = scwin.vIsurCd;
                arrPar[1] = scwin.dts.getCellData(scwin.dts.getRowPosition(), "COM_NM");
                arrPar[5] = "";
                arrPar[6] = "2";
            }
        }
    }
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = scwin.dts.getCellData(scwin.dts.getRowPosition(), "bz_procs_no");
    return arrPar.length;
};

